import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { sha256 } from './lib/canonicalize.mjs';
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const TOOL = path.join(ROOT, 'archive/tools/logic-visual-audit'); const OUT = path.join(TOOL, 'reports');
const fileHash = (relative) => { const bytes = fs.readFileSync(path.join(ROOT, relative.replaceAll('/', path.sep))); return { path: relative, bytes: bytes.length, sha256: `sha256:${crypto.createHash('sha256').update(bytes).digest('hex')}` }; };
const json = (name) => JSON.parse(fs.readFileSync(path.join(OUT, name), 'utf8'));
const preflight = json('rule_preflight.json'); const target = json('target_inventory_summary.json'); const v1 = json('v1_evidence_freeze.json'); const v2 = json('v2_evidence_freeze.json'); const extraction = json('v2_observed_extraction.json'); const mutation = json('mutation_qualification.json'); const corpus = json('corpus_pilot.json'); const finalRequirementMap = json('final_visual_requirement_map.json'); const denominator = fs.existsSync(path.join(OUT, 'c_denominator_frozen.json')) ? json('c_denominator_frozen.json') : json('c_denominator.json');
const toolFiles = ['archive/tools/logic-visual-audit/lib/canonicalize.mjs', 'archive/tools/logic-visual-audit/verify-rule-preflight.mjs', 'archive/tools/logic-visual-audit/extract-v2-observed-facts.mjs', 'archive/tools/logic-visual-audit/run-mutation-qualification.mjs', 'archive/tools/logic-visual-audit/verify-item-semantic-parity.mjs', 'archive/tools/logic-visual-audit/specs/logic-visual-fact-schema-v1.json', 'archive/tools/logic-visual-audit/specs/fact-canonicalization-spec-v1.json', 'archive/tools/logic-visual-audit/specs/semantic-projection-spec-v1.json', 'archive/tools/logic-visual-audit/specs/mutation-expected-detector-map-v1.json', 'archive/engine.html'];
const files = Object.fromEntries(toolFiles.map((file) => [path.basename(file), fileHash(file)]));
const bundle = { generatedAtKst: '2026-09-05', ruleStatus: preflight.ruleStatus, effectiveRulesetSha: sha256({ ruleRoutingBundleSha: preflight.ruleRoutingBundleSha, overlayRuleSha: preflight.rules.find((rule) => rule.role === 'UNIT_OVERLAY_CANDIDATE')?.sha256 || null }), ruleRoutingBundleSha: preflight.ruleRoutingBundleSha, overlayRuleSha: preflight.rules.find((rule) => rule.role === 'UNIT_OVERLAY_CANDIDATE')?.sha256 || null, factSchemaSha: files['logic-visual-fact-schema-v1.json'].sha256, logicVisualFactCanonicalizationSpecSha: files['fact-canonicalization-spec-v1.json'].sha256, semanticProjectionSpecSha: files['semantic-projection-spec-v1.json'].sha256, mutationExpectedDetectorMapSha: mutation.mutationExpectedDetectorMapSha, calibrationCorpusSha: corpus.calibrationCorpusSha || null, holdoutCorpusSha: corpus.holdoutCorpusSha || null, mutationCorpusSha: sha256(fs.readFileSync(path.join(TOOL, 'corpus/adversarial/mutations.jsonl'), 'utf8')), targetInventorySha: sha256(target), finalVisualRequirementMapSha: finalRequirementMap.finalVisualRequirementMapSha, cDenominatorStatus: denominator.status, cDenominatorInputSha: denominator.cDenominatorInputSha, v1FirstPassEvidenceSha: v1.firstPassEvidenceSha, v2FirstPassEvidenceSha: v2.firstPassEvidenceSha, observedExtractionEngineSha: extraction.extractionEngineSha, toolFiles, files, qualificationInputBundleSha: null };
const bundleWithoutFinalSha = { ...bundle }; delete bundleWithoutFinalSha.qualificationInputBundleSha; bundle.qualificationInputBundleSha = sha256(bundleWithoutFinalSha);
fs.writeFileSync(path.join(OUT, 'qualification_input_bundle.json'), JSON.stringify(bundle, null, 2) + '\n', 'utf8');
console.log(JSON.stringify({ qualificationInputBundleSha: bundle.qualificationInputBundleSha, effectiveRulesetSha: bundle.effectiveRulesetSha, ruleStatus: bundle.ruleStatus }, null, 2));
